export const WORLD_BRAND_LOGOS_BY_ID: Record<string, WorldBrandLogo> = Object.fromEntries(
  WORLD_BRAND_LOGOS.map((l) => [l.id, l])
);

export const BRAND_CATEGORIES: BrandCategory[] = [
  'Tech',
  'Automotive',
  'Sports & Apparel',
  'Food & Drink',
  'Entertainment & Gaming',
  'Retail & Finance',
];

export function getLogosByCategory(category?: BrandCategory | 'all'): WorldBrandLogo[] {
  if (!category || category === 'all') return WORLD_BRAND_LOGOS;
  return WORLD_BRAND_LOGOS.filter((l) => l.category === category);
}

export function getRandomLogo(category?: BrandCategory | 'all'): WorldBrandLogo {
  const list = getLogosByCategory(category);
  return list[Math.floor(Math.random() * list.length)]!;
}
